class Solution {
public:
    int subarraysWithMoreZerosThanOnes(vector<int>& nums) {
        long long mod = 1000000007;
        int n = nums.size();
        int offset = n + 1;
        vector<int> tree(2 * n + 5, 0);

        auto query = [&](int idx) -> int {
            int s = 0;
            while (idx > 0) {
                s = (s + tree[idx]) % mod;
                idx -= idx & (-idx);
            }
            return s;
        };

        auto update = [&](int idx, int val) {
            while (idx < (int)tree.size()) {
                tree[idx] = (tree[idx] + val) % mod;
                idx += idx & (-idx);
            }
        };

        update(offset, 1);
        int curr_pref = 0;
        long long ans = 0;
        for (int x : nums) {
            curr_pref += (x == 1 ? 1 : -1);
            ans = (ans + query(curr_pref + offset - 1)) % mod;
            update(curr_pref + offset, 1);
        }
        return ans;
    }
};

class Solution {
    public int subarraysWithMoreZerosThanOnes(int[] nums) {
        long mod = 1000000007L;
        int n = nums.length;
        int offset = n + 1;
        long[] tree = new long[2 * n + 5];

        java.util.function.IntFunction<Long> query = (idx) -> {
            long s = 0;
            while (idx > 0) {
                s = (s + tree[idx]) % mod;
                idx -= idx & (-idx);
            }
            return s;
        };

        java.util.function.BiConsumer<Integer, Long> update = (idx, val) -> {
            while (idx < tree.length) {
                tree[idx] = (tree[idx] + val) % mod;
                idx += idx & (-idx);
            }
        };

        update.accept(offset, 1L);
        int currPref = 0;
        long ans = 0;
        for (int x : nums) {
            currPref += (x == 1 ? 1 : -1);
            ans = (ans + query.apply(currPref + offset - 1)) % mod;
            update.accept(currPref + offset, 1L);
        }
        return (int)ans;
    }
}

